import type { Category, Product } from '@califnco/shared';
export const PHOTO_LIBRARY = {
  hero: 'data:image/webp;base64,',
  install: 'data:image/webp;base64,',
  family: 'data:image/webp;base64,',
  purifier_domestic: 'data:image/webp;base64,',
  purifier_domestic_detail: 'data:image/webp;base64,',
  purifier_alkaline: 'data:image/webp;base64,',
  purifier_alkaline_detail: 'data:image/webp;base64,',
  purifier_commercial: 'data:image/webp;base64,',
  purifier_commercial_detail: 'data:image/webp;base64,',
  dispenser: 'data:image/webp;base64,',
  dispenser_detail: 'data:image/webp;base64,',
  pump: 'data:image/webp;base64,',
  pump_detail: 'data:image/webp;base64,',
  filter: 'data:image/webp;base64,',
  filter_detail: 'data:image/webp;base64,',
  cartridge: 'data:image/webp;base64,',
  cartridge_detail: 'data:image/webp;base64,',
  spare: 'data:image/webp;base64,',
  spare_detail: 'data:image/webp;base64,',
} as const;
export type PhotoKey = keyof typeof PHOTO_LIBRARY;


// Discover any custom photographs dropped into src/assets/images/** at build time.
const files =
  typeof import.meta !== 'undefined' && typeof import.meta.glob === 'function'
    ? (import.meta.glob('../assets/images/**/*.{jpg,jpeg,png,webp,avif}', {
        eager: true,
        query: '?url',
        import: 'default',
      }) as Record<string, string>)
    : {};

const index = new Map<string, string>();
for (const [path, url] of Object.entries(files)) {
  const m = path.match(/images\/([^/]+)\/(.+)\.[a-z]+$/i);
  if (m) index.set(`${m[1]}/${m[2]}`.toLowerCase(), url);
}
const find = (folder: string, name: string) => index.get(`${folder}/${name}`.toLowerCase());

export interface ImagePreset {
  key: PhotoKey;
  label: string;
  category: Category | 'lifestyle';
  url: string;
}

export const IMAGE_PRESETS: ImagePreset[] = [
  { key: 'purifier_domestic', label: 'AquaPure RO+UV Domestic Purifier (White & Navy)', category: 'purifiers', url: PHOTO_LIBRARY.purifier_domestic },
  { key: 'purifier_alkaline', label: 'Alkaline & Pro Stainless Steel RO+UV Purifier', category: 'purifiers', url: PHOTO_LIBRARY.purifier_alkaline },
  { key: 'purifier_commercial', label: 'Commercial Skid-Mounted Twin-Membrane RO Plant', category: 'purifiers', url: PHOTO_LIBRARY.purifier_commercial },
  { key: 'dispenser', label: 'Bottom-Loading Hot & Cold Floor Dispenser', category: 'dispensers', url: PHOTO_LIBRARY.dispenser },
  { key: 'pump', label: '24V DC High-Pressure RO Diaphragm Booster Pump', category: 'pumps', url: PHOTO_LIBRARY.pump },
  { key: 'filter', label: '10-Inch Sediment, Carbon Block & Housing Set', category: 'filters', url: PHOTO_LIBRARY.filter },
  { key: 'cartridge', label: 'RO Membrane, Inline Mineralizer & UV-C Lamp Set', category: 'cartridges', url: PHOTO_LIBRARY.cartridge },
  { key: 'spare', label: 'Chrome Gooseneck Faucet, Solenoid, SMPS & Fittings', category: 'spare-parts', url: PHOTO_LIBRARY.spare },
  { key: 'hero', label: 'Countertop RO Purifier in Modern Kitchen', category: 'lifestyle', url: PHOTO_LIBRARY.hero },
  { key: 'install', label: 'Certified Technician Installation & TDS Testing', category: 'lifestyle', url: PHOTO_LIBRARY.install },
];

export const heroPhoto = (): string => find('hero', 'hero') ?? PHOTO_LIBRARY.hero;
export const familyPhoto = (): string => find('lifestyle', 'family') ?? PHOTO_LIBRARY.family;
export const installPhoto = (): string => find('installation', 'install') ?? PHOTO_LIBRARY.install;

const CATEGORY_PHOTO_MAP: Record<string, string> = {
  purifiers: PHOTO_LIBRARY.purifier_domestic,
  dispensers: PHOTO_LIBRARY.dispenser,
  pumps: PHOTO_LIBRARY.pump,
  filters: PHOTO_LIBRARY.filter,
  cartridges: PHOTO_LIBRARY.cartridge,
  'spare-parts': PHOTO_LIBRARY.spare,
};

export const categoryImage = (c: string): string =>
  find('categories', c) ?? CATEGORY_PHOTO_MAP[c] ?? PHOTO_LIBRARY.purifier_domestic;

export const hasPhoto = (url: string): boolean => Boolean(url && !url.endsWith('.svg'));

const ALKALINE_SKUS = new Set(['CF-P-RO10', 'CF-P-ALK', 'CF-P-UC12']);
const COMMERCIAL_SKUS = new Set(['CF-P-COM25', 'CF-P-COM50']);

function defaultGalleryForSku(sku: string, category?: string): string[] {
  const upper = sku.toUpperCase();
  if ((category === 'purifiers' || upper.startsWith('CF-P-')) && (COMMERCIAL_SKUS.has(upper) || upper.includes('COM'))) {
    return [PHOTO_LIBRARY.purifier_commercial, PHOTO_LIBRARY.purifier_commercial_detail];
  }
  if ((category === 'purifiers' || upper.startsWith('CF-P-')) && (ALKALINE_SKUS.has(upper) || upper.includes('ALK') || upper.includes('UC'))) {
    return [PHOTO_LIBRARY.purifier_alkaline, PHOTO_LIBRARY.purifier_alkaline_detail, PHOTO_LIBRARY.hero];
  }
  if (category === 'purifiers' || upper.startsWith('CF-P-')) {
    return [PHOTO_LIBRARY.purifier_domestic, PHOTO_LIBRARY.purifier_domestic_detail, PHOTO_LIBRARY.install];
  }
  if (category === 'dispensers' || upper.startsWith('CF-D-')) {
    return [PHOTO_LIBRARY.dispenser, PHOTO_LIBRARY.dispenser_detail];
  }
  if (category === 'pumps' || upper.startsWith('CF-PU-')) {
    return [PHOTO_LIBRARY.pump, PHOTO_LIBRARY.pump_detail];
  }
  if (category === 'filters' || upper.startsWith('CF-F-')) {
    return [PHOTO_LIBRARY.filter, PHOTO_LIBRARY.filter_detail];
  }
  if (category === 'cartridges' || upper.startsWith('CF-C-')) {
    return [PHOTO_LIBRARY.cartridge, PHOTO_LIBRARY.cartridge_detail];
  }
  if (category === 'spare-parts' || upper.startsWith('CF-S-')) {
    return [PHOTO_LIBRARY.spare, PHOTO_LIBRARY.spare_detail];
  }
  return [PHOTO_LIBRARY.purifier_domestic, PHOTO_LIBRARY.purifier_domestic_detail];
}

export function resolveImageRef(ref: string | undefined, sku = '', category?: string): string {
  if (!ref) return defaultGalleryForSku(sku, category)[0]!;
  if (ref.startsWith('preset:')) {
    const key = ref.slice(7) as PhotoKey;
    if (key in PHOTO_LIBRARY) return PHOTO_LIBRARY[key];
  }
  if (ref in PHOTO_LIBRARY) {
    return PHOTO_LIBRARY[ref as PhotoKey];
  }
  // Replace legacy SVG category placeholder path with real studio photography
  if (ref.startsWith('/img/') && ref.endsWith('.svg')) {
    return defaultGalleryForSku(sku, category)[0]!;
  }
  return ref;
}

/** Gallery for a product: custom uploaded/selected photos first, build-time SKU assets next, then studio photography for the SKU. */
export function productImages(p: Pick<Product, 'sku' | 'image'> & { category?: string; gallery?: string[] }): string[] {
  const out: string[] = [];

  // 1. Check build-time dropped files in src/assets/images/{products,filters}/<SKU>
  for (const folder of ['products', 'filters']) {
    const main = find(folder, p.sku);
    if (main) out.push(main);
    for (let i = 2; i <= 6; i++) {
      const x = find(folder, `${p.sku}_${i}`);
      if (x) out.push(x);
    }
  }

  // 2. Check custom product image set by admin (if not a legacy /img/*.svg placeholder)
  if (p.image && !(p.image.startsWith('/img/') && p.image.endsWith('.svg'))) {
    const resolved = resolveImageRef(p.image, p.sku, p.category);
    if (!out.includes(resolved)) out.unshift(resolved);
  }

  // 3. Check additional gallery images on product record
  if (Array.isArray(p.gallery)) {
    for (const g of p.gallery) {
      if (g) {
        const resolved = resolveImageRef(g, p.sku, p.category);
        if (!out.includes(resolved)) out.push(resolved);
      }
    }
  }

  // 4. Fill with SKU studio photography gallery
  for (const studioUrl of defaultGalleryForSku(p.sku, p.category)) {
    if (!out.includes(studioUrl)) out.push(studioUrl);
  }

  return out.length ? out : [PHOTO_LIBRARY.purifier_domestic];
}

export const productImage = (p: Pick<Product, 'sku' | 'image'> & { category?: string; gallery?: string[] }): string =>
  productImages(p)[0]!;
